25	public class CsrfRequestResponseReactiveFilter {
26	    private static final Logger LOG = Logger.getLogger(CsrfRequestResponseReactiveFilter.class);
27	
28	    /**
29	     * CSRF token key.
30	     */
31	    private static final String CSRF_TOKEN_KEY = "csrf_token";
32	    private static final String CSRF_TOKEN_BYTES_KEY = "csrf_token_bytes";
33	    private static final String NEW_COOKIE_REQUIRED = "true";
34	
35	    /**
36	     * CSRF token verification status.
37	     */
38	    private static final String CSRF_TOKEN_VERIFIED = "csrf_token_verified";
39	
40	    private final SecureRandom secureRandom = new SecureRandom();
41	
42	    @Inject
43	    Instance<CsrfReactiveConfig> configInstance;
44	
45	    public CsrfRequestResponseReactiveFilter() {
46	    }
47	
48	    /**
49	     * If the request method is safe ({@code GET}, {@code HEAD} or {@code OPTIONS}):
50	     * <ul>
51	     * <li>Sets a {@link RoutingContext} key by the name {@value #CSRF_TOKEN_KEY} that contains a randomly generated Base64
52	     * encoded string, unless such a cookie was already sent in the incoming request.</li>
53	     * </ul>
54	     * If the request method is unsafe, requires the following:
55	     * <ul>
56	     * <li>The request contains a valid CSRF token cookie set in response to a previous request (see above).</li>
57	     * <li>A request entity is present.</li>
58	     * <li>The request {@code Content-Type} is {@value MediaType#APPLICATION_FORM_URLENCODED}.</li>
59	     * <li>The request entity contains a form parameter with the name
60	     * {@value #CSRF_TOKEN_KEY} and value that is equal to the one supplied in the cookie.</li>
61	     * </ul>
62	     */
63	    @ServerRequestFilter
64	    @WithFormRead
65	    public void filter(ResteasyReactiveContainerRequestContext requestContext, RoutingContext routing) {
66	        final CsrfReactiveConfig config = this.configInstance.get();
67	
68	        String cookieToken = getCookieToken(routing, config);
69	        if (cookieToken != null) {
70	            try {
71	                int cookieTokenSize = Base64.getUrlDecoder().decode(cookieToken).length;
72	                // HMAC SHA256 output is 32 bytes long
73	                int expectedCookieTokenSize = config.tokenSignatureKey.isPresent() ? 32 : config.tokenSize;
74	                if (cookieTokenSize != expectedCookieTokenSize) {
75	                    LOG.debugf("Invalid CSRF token cookie size: expected %d, got %d", expectedCookieTokenSize,
76	                            cookieTokenSize);
77	                    requestContext.abortWith(badClientRequest());
78	                    return;
79	                }
80	            } catch (IllegalArgumentException e) {
81	                LOG.debugf("Invalid CSRF token cookie: %s", cookieToken);
82	                requestContext.abortWith(badClientRequest());
83	                return;
84	            }
85	        }
86	
87	        if (requestMethodIsSafe(requestContext)) {
88	            // safe HTTP method, tolerate the absence of a token
89	            if (isCsrfTokenRequired(routing, config)) {
90	                if (cookieToken == null) {
91	                    generateNewCsrfToken(routing, config);
92	                } else {
93	                    String csrfTokenHeaderParam = requestContext.getHeaderString(config.tokenHeaderName);
94	                    if (csrfTokenHeaderParam != null) {
95	                        LOG.debugf("CSRF token found in the token header");
96	                        // Verify the header, make sure the header value, possibly signed, is returned as the next cookie value
97	                        verifyCsrfToken(requestContext, routing, config, cookieToken, csrfTokenHeaderParam);
98	                    } else if (!config.tokenSignatureKey.isEmpty()) {
99	                        // If the signature is required, then we can not use the current cookie value
100	                        // as the HTML form token key because it represents a signed value of the previous key
101	                        // and it will lead to the double-signing issue if this value is reused as the key.
102	                        // It should be fine for simple HTML forms anyway
103	                        generateNewCsrfToken(routing, config);
104	                    } else {
105	                        // Make sure the same cookie value is returned
106	                        routing.put(CSRF_TOKEN_KEY, cookieToken);
107	                        routing.put(CSRF_TOKEN_BYTES_KEY, Base64.getUrlDecoder().decode(cookieToken));
108	                    }
109	                }
110	                routing.put(NEW_COOKIE_REQUIRED, true);
111	            }
112	        } else if (config.verifyToken) {
113	            // unsafe HTTP method, token is required
114	
115	            // Check the header first
116	            String csrfTokenHeaderParam = requestContext.getHeaderString(config.tokenHeaderName);
117	            if (csrfTokenHeaderParam != null) {
118	                LOG.debugf("CSRF token found in the token header");
119	                verifyCsrfToken(requestContext, routing, config, cookieToken, csrfTokenHeaderParam);
120	                return;
121	            }
122	
123	            // Check the form field
124	            MediaType mediaType = requestContext.getMediaType();
125	            if (!isMatchingMediaType(mediaType, MediaType.APPLICATION_FORM_URLENCODED_TYPE)
126	                    && !isMatchingMediaType(mediaType, MediaType.MULTIPART_FORM_DATA_TYPE)) {
127	                if (config.requireFormUrlEncoded) {
128	                    LOG.debugf("Request has the wrong media type: %s", mediaType);
129	                    requestContext.abortWith(badClientRequest());
130	                    return;
131	                } else {
132	                    LOG.debugf("Request has the media type: %s, skipping the token verification",
133	                            mediaType);
134	                    return;
135	                }
136	            }
137	
138	            if (!requestContext.hasEntity()) {
139	                LOG.debug("Request has no entity");
140	                requestContext.abortWith(badClientRequest());
141	                return;
142	            }
143	
144	            ResteasyReactiveRequestContext rrContext = (ResteasyReactiveRequestContext) requestContext
145	                    .getServerRequestContext();
146	            String csrfTokenFormParam = (String) rrContext.getFormParameter(config.formFieldName, true, false);
147	            LOG.debugf("CSRF token found in the form parameter");
148	            verifyCsrfToken(requestContext, routing, config, cookieToken, csrfTokenFormParam);
149	
150	        } else if (cookieToken == null) {
151	            LOG.debug("CSRF token is not found");
152	            requestContext.abortWith(badClientRequest());
153	        }
154	    }
